package com.calisthenics.diagnostic.preprocessing

import kotlin.test.Test
import kotlin.test.assertContentEquals

/**
 * Randomized edge-dimension table cross-checked against the Python reference
 * implementation (`reference/src/observation_contracts/preprocessing.py`,
 * `scale_pad_rgb24`), covering identity, extreme upscale/downscale, non-square
 * aspect ratios, and 1-pixel source/target dimensions.
 */
private data class EdgeCase(
    val sourceWidth: Int,
    val sourceHeight: Int,
    val targetWidth: Int,
    val targetHeight: Int,
    val inputHex: String,
    val expectedOutputHex: String,
)

private fun String.hexToByteArray(): ByteArray {
    require(length % 2 == 0)
    return ByteArray(length / 2) { i ->
        substring(i * 2, i * 2 + 2).toInt(16).toByte()
    }
}

