    EdgeCase(1, 1, 1, 1, "d50598", "d50598"),
    EdgeCase(1, 1, 5, 3, "bc638a", "000000bc638abc638abc638a000000000000bc638abc638abc638a000000000000bc638abc638abc638a000000"),
    EdgeCase(2, 3, 3, 2, "df52bf3fdd85595fb52ed3554b692761aea4", "0000007c989b000000000000518f6d000000"),
    EdgeCase(3, 2, 2, 3, "0ceaad0dd40103535b9232d4365dc077a814", "0000000000004491a9368442000000000000"),
    EdgeCase(4, 4, 4, 4, "763dff6e5f83de4215549a044c75b3af50c5a506191fe328c65b05bc6e3ef61f07fba6d767ba3d4c28fd54ab76685353", "763dff6e5f83de4215549a044c75b3af50c5a506191fe328c65b05bc6e3ef61f07fba6d767ba3d4c28fd54ab76685353"),
    EdgeCase(1, 5, 5, 1, "934c2e014b01fd5e3187cf21ebd55d", "000000000000fd5e31000000000000"),
    EdgeCase(7, 3, 3, 7, "7c5e0dbea95aca5b5b7fd3d5a63d22eb63674577a995401e85da16ba37224fbe128ce3bccd9de5879ffcf51987e40f70b045012a0f3860cbfb5d8bb26a99a1", "0000000000000000000000000000000000000000000000000000008aa7194fbe12b69eed000000000000000000000000000000000000000000000000000000"),
    EdgeCase(10, 10, 1, 1, "", "76647b"),
