    EdgeCase(5, 5, 1, 5, "e14f2bb7260a5b411a2d5eafa52a082897c343e19decda82f250412ccdc5afcfc61c00808f80045ed3dfd4511616a0d9fbf1687588c59030d122ad394fc9208342b048183b9f876bd81b92", "0000000000008f8004000000000000"),
