class ScalePadEdgeDimensionTableTest {
    @Test
    fun everyEdgeDimensionCaseMatchesThePythonReferenceOutput() {
        for (case in EDGE_DIMENSION_CASES) {
            val actual = scalePadRgb24(
                case.inputHex.hexToByteArray(),
                case.sourceWidth,
                case.sourceHeight,
                case.targetWidth,
                case.targetHeight,
            )
            assertContentEquals(
                case.expectedOutputHex.hexToByteArray(),
                actual,
                "mismatch for ${case.sourceWidth}x${case.sourceHeight} -> ${case.targetWidth}x${case.targetHeight}",
            )
        }
    }
}
